dashboard.definition:
{
	"title": "Splunk Use Cases",
	"description": "",
	"inputs": {
		"input_global_trp": {
			"options": {
				"defaultValue": "2026-01-01T00:00:00.000Z,2026-01-15T00:00:00.000Z",
				"token": "global_time"
			},
			"title": "Global Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		},
		"visualizations": {
			"global": {
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
