	"dataSources": {
		"ds_0sYasD3M": {
			"name": "events over tim and bytes",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:cisco:asa\" action IN (allowed,teardown,blocked,executed)\n| timechart span=10m c by action\n| join _time \n    [search index=fake_tshrt sourcetype=\"FAKE:cisco:asa\"  bytes=*\n    | timechart span=10m sum(bytes) as bytes ]",
				"queryParameters": {
					"sampleRatio": 1
				}
			},
			"type": "ds.search"
		},
		"ds_4RJIZ23c": {
			"name": "Map iplocation DEST ip",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:cisco:asa\" dest=*\n| iplocation dest\n| geostats c by Country",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_5ENgTRB8": {
			"name": "Dest with most events",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:cisco:asa\" dest=* \n| stats c sum(bytes) as bytes by dest\n| sort - c",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_6WjVDkNb": {
			"name": "hosts",
			"options": {
				"query": "| tstats c where index=fake_tshrt by host\n| sort - c"
			},
			"type": "ds.search"
		},
		"ds_7P0YDyNj": {
			"name": "Action Over Time copy 2",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:cisco:asa\" action=*\n| stats c by action",
				"queryParameters": {
