		"ds_avg_delivery_time": {
			"name": "Avg Delivery Time",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=statusHistory{}.status output=statuses | spath path=statusHistory{}.timestamp output=timestamps | eval created_idx=mvfind(statuses,\"created\"), delivered_idx=mvfind(statuses,\"delivered\") | eval created_time=strptime(mvindex(timestamps,created_idx),\"%Y-%m-%dT%H:%M:%SZ\") | eval delivered_time=strptime(mvindex(timestamps,delivered_idx),\"%Y-%m-%dT%H:%M:%SZ\") | eval total_hours=round((delivered_time-created_time)/3600,1) | stats avg(total_hours) as avg_delivery_hours | eval avg_delivery_hours=round(avg_delivery_hours,1)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_avg_items_per_order": {
			"name": "Avg Items Per Order",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=items{} output=items | eval item_count=mvcount(items) | stats avg(item_count) as avg_items",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_avg_order_value": {
			"name": "Avg Order Value",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=pricing.total output=total | stats avg(total) as avg_order_value",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_browser_breakdown": {
			"name": "Browser Breakdown",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:access_combined\" | eval browser=case(match(useragent,\"Chrome\"),\"Chrome\",match(useragent,\"Safari\") AND NOT match(useragent,\"Chrome\"),\"Safari\",match(useragent,\"Firefox\"),\"Firefox\",match(useragent,\"Edge\"),\"Edge\",1=1,\"Other\") | stats count as Visits by browser",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cart_abandonment": {
			"name": "Cart Abandonment",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:access_combined\" tshirtcid=* | stats max(eval(if(uri=\"/cart\",1,0))) as cart, max(eval(if(uri=\"/checkout/complete\",1,0))) as complete by tshirtcid | stats sum(cart) as carts, sum(complete) as purchases | eval cart_abandonment=round(((carts-purchases)/carts)*100,1)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_category_trend": {
			"name": "Category Trend",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=items{} output=items | mvexpand items | spath input=items | timechart span=1d sum(lineTotal) by category",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_conversion_rate": {
			"name": "Conversion Rate",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:access_combined\" | stats dc(eval(if(uri=\"/\", session_id, null()))) as homepage, dc(eval(if(uri=\"/checkout/complete\", session_id, null()))) as completed | eval conversion_rate=round((completed/homepage)*100,1)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_delivery_by_region": {
			"name": "Delivery Time by Region",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=statusHistory{}.status output=statuses | spath path=statusHistory{}.timestamp output=timestamps | spath path=shippingAddress.region output=region | eval created_idx=mvfind(statuses,\"created\"), delivered_idx=mvfind(statuses,\"delivered\") | eval created_time=strptime(mvindex(timestamps,created_idx),\"%Y-%m-%dT%H:%M:%SZ\") | eval delivered_time=strptime(mvindex(timestamps,delivered_idx),\"%Y-%m-%dT%H:%M:%SZ\") | eval total_hours=round((delivered_time-created_time)/3600,1) | stats avg(total_hours) as \"Avg Hours\" by region | sort - \"Avg Hours\" | head 10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_device_breakdown": {
			"name": "Device Breakdown",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:access_combined\" | eval device=case(match(useragent,\"iPhone|Android.*Mobile\"),\"Mobile\",match(useragent,\"iPad|Android(?!.*Mobile)\"),\"Tablet\",1=1,\"Desktop\") | stats count as Visits by device",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_e9svVC25": {
			"name": "Allowed over time",
			"options": {
				"extend": "ds_0sYasD3M",
				"query": "| table _time allowed"
			},
			"type": "ds.chain"
		},
		"ds_fulfillment_timeline": {
			"name": "Order Fulfillment Timeline",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=orderId | spath path=statusHistory{}.status output=statuses | spath path=statusHistory{}.timestamp output=timestamps | spath path=shippingAddress.region output=region | eval created_idx=mvfind(statuses,\"created\"), shipped_idx=mvfind(statuses,\"shipped\"), delivered_idx=mvfind(statuses,\"delivered\") | eval created_time=strptime(mvindex(timestamps,created_idx),\"%Y-%m-%dT%H:%M:%SZ\") | eval shipped_time=strptime(mvindex(timestamps,shipped_idx),\"%Y-%m-%dT%H:%M:%SZ\") | eval delivered_time=strptime(mvindex(timestamps,delivered_idx),\"%Y-%m-%dT%H:%M:%SZ\") | eval processing_hrs=round((shipped_time-created_time)/3600,1) | eval delivery_hrs=round((delivered_time-shipped_time)/3600,1) | eval total_hrs=round((delivered_time-created_time)/3600,1) | table orderId region processing_hrs delivery_hrs total_hrs | sort - total_hrs | head 15 | rename orderId as \"Order ID\", region as \"Region\", processing_hrs as \"Processing (hrs)\", delivery_hrs as \"Shipping (hrs)\", total_hrs as \"Total (hrs)\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_gW3RtdkR": {
			"name": "host",
			"options": {
				"query": "| tstats dc(host) where index=fake_tshrt",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
