				"query": "index=fake_tshrt sourcetype=\"FAKE:o365:reporting:messagetrace\" (SenderAddress=\"*lottery*\" OR SenderAddress=\"*secure-banking*\" OR SenderAddress=\"*amaz0n*\" OR SenderAddress=\"*nigeria*\" OR SenderAddress=\"*pharmacy*\" OR SenderAddress=\"*m1crosoft-secure*\" OR Status=\"FilteredAsSpam\" OR Subject=\"*URGENT*\" OR Subject=\"*won*\" OR Subject=\"*Verify*\" OR Subject=\"*Action Required*\" OR Subject=\"*90%*\") | eval keyword=case(match(Subject,\"(?i)urgent\"), \"URGENT\", match(Subject,\"(?i)won\"), \"Prize/Lottery\", match(Subject,\"(?i)verify\"), \"Verify Account\", match(Subject,\"(?i)action required\"), \"Action Required\", match(Subject,\"(?i)90%|offer\"), \"Fake Offer\", match(Subject,\"(?i)suspicious\"), \"Suspicious Activity\", 1=1, \"Other\") | stats count by keyword | sort - count",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sec_phishing_over_time": {
			"name": "SOC - Phishing Over Time",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:o365:reporting:messagetrace\" (SenderAddress=\"*lottery*\" OR SenderAddress=\"*secure-banking*\" OR SenderAddress=\"*amaz0n*\" OR SenderAddress=\"*nigeria*\" OR SenderAddress=\"*pharmacy*\" OR SenderAddress=\"*m1crosoft-secure*\" OR Status=\"FilteredAsSpam\" OR Subject=\"*URGENT*Verify*\" OR Subject=\"*won*$*\" OR Subject=\"*Action Required*\") | eval status=if(Status=\"FilteredAsSpam\" OR action=\"blocked\", \"Blocked\", \"Delivered\") | timechart span=1h count by status",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sec_phishing_senders": {
			"name": "SOC - Top Phishing Senders",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:o365:reporting:messagetrace\" (SenderAddress=\"*lottery*\" OR SenderAddress=\"*secure-banking*\" OR SenderAddress=\"*amaz0n*\" OR SenderAddress=\"*nigeria*\" OR SenderAddress=\"*pharmacy*\" OR SenderAddress=\"*m1crosoft-secure*\") | rex field=SenderAddress \"@(?<sender_domain>.+)\" | stats count as Emails by sender_domain | sort - Emails | head 10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sec_phishing_status": {
			"name": "SOC - Phishing by Status",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:o365:reporting:messagetrace\" (SenderAddress=\"*lottery*\" OR SenderAddress=\"*secure-banking*\" OR SenderAddress=\"*amaz0n*\" OR SenderAddress=\"*nigeria*\" OR SenderAddress=\"*pharmacy*\" OR SenderAddress=\"*m1crosoft-secure*\" OR Status=\"FilteredAsSpam\" OR Subject=\"*URGENT*Verify*\" OR Subject=\"*won*$*\" OR Subject=\"*Action Required*\") | eval phish_status=case(Status=\"FilteredAsSpam\", \"Blocked\", Status=\"Delivered\", \"Delivered\", Status=\"Failed\", \"Failed\", 1=1, Status) | stats count by phish_status",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sec_phishing_targets": {
			"name": "SOC - Top Phishing Targets",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:o365:reporting:messagetrace\" (SenderAddress=\"*lottery*\" OR SenderAddress=\"*secure-banking*\" OR SenderAddress=\"*amaz0n*\" OR SenderAddress=\"*nigeria*\" OR SenderAddress=\"*pharmacy*\" OR SenderAddress=\"*m1crosoft-secure*\" OR Status=\"FilteredAsSpam\" OR Subject=\"*URGENT*Verify*\" OR Subject=\"*won*$*\" OR Subject=\"*Action Required*\") | stats count as Attempts dc(SenderAddress) as \"Unique Senders\" by RecipientAddress | sort - Attempts | head 15 | rename RecipientAddress as \"Target User\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sec_phishing_total": {
			"name": "SOC - Phishing Total",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:o365:reporting:messagetrace\" (SenderAddress=\"*lottery*\" OR SenderAddress=\"*secure-banking*\" OR SenderAddress=\"*amaz0n*\" OR SenderAddress=\"*nigeria*\" OR SenderAddress=\"*pharmacy*\" OR SenderAddress=\"*m1crosoft-secure*\" OR Status=\"FilteredAsSpam\" OR Subject=\"*URGENT*Verify*\" OR Subject=\"*won*$*\" OR Subject=\"*Action Required*\") | stats count as phishing_total",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sec_severity_warnings": {
			"name": "SOC - Severity Warnings",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:cisco:asa\" severity_level IN (warning, notification) | stats count as warnings",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sec_top_dest_ports": {
			"name": "SOC - Top Destination Ports",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:cisco:asa\" dest_port=* | stats count as Connections by dest_port | sort - Connections | head 10 | rename dest_port as Port",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sec_top_src_ips": {
			"name": "SOC - Top Source IPs",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:cisco:asa\" src=* | stats count as Events sum(bytes) as Bytes by src | sort - Events | head 10 | rename src as \"Source IP\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sec_total_events": {
			"name": "SOC - Total Security Events",
			"options": {
				"query": "index=fake_tshrt sourcetype IN (\"cisco:asa\", \"azure:aad:signin\", \"azure:aad:audit\", \"aws:cloudtrail\", \"WinEventLog\") | stats count as total_events",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sec_traffic_interface": {
			"name": "SOC - Traffic by Interface",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:cisco:asa\" dest_interface=* | stats count as Connections by dest_interface | rename dest_interface as Interface",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sec_unique_src_ips": {
			"name": "SOC - Unique Source IPs",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:cisco:asa\" src=* | stats dc(src) as unique_ips",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_shipping_breakdown": {
			"name": "Shipping Cost Breakdown",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=pricing.shipping output=shipping | spath path=shippingAddress.country output=country | eval shipping_type=if(country=\"United States\",\"Domestic ($8)\",\"International ($15)\") | stats count as Orders sum(shipping) as Revenue by shipping_type",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_tCfq542K": {
			"name": "Events",
			"options": {
				"query": "| tstats c where index=fake_tshrt by _time sourcetype span=1h\n| timechart sum(c) span=1h by sourcetype limit=25",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_top_cities": {
			"name": "Top Cities",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=shippingAddress.city output=city | spath path=pricing.total output=total | stats sum(total) as Revenue by city | sort -Revenue | head 10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_top_products": {
			"name": "Top Products",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=items{} output=items | mvexpand items | spath input=items | stats sum(lineTotal) as Revenue by name | sort -Revenue | head 10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_top_regions": {
			"name": "Top Regions",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=shippingAddress.region output=region | spath path=pricing.total output=total | stats sum(total) as Revenue by region | sort -Revenue | head 10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_top_search_terms": {
			"name": "Top Search Terms",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:access_combined\" uri=\"/api/v1/search*\" | rex field=uri \"q=(?<term>[^&]+)\" | stats count as Searches by term | sort -Searches | head 10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_total_downtime": {
			"name": "Total Downtime",
			"options": {
				"query": "| makeresults | eval total_downtime=90",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_total_orders": {
			"name": "Total Orders",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | stats dc(orderId) as total_orders",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_total_revenue": {
			"name": "Total Revenue",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=pricing.total output=total | stats sum(total) as total_revenue | eval total_revenue=round(total_revenue,0)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_total_shipping": {
			"name": "Total Shipping Revenue",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=pricing.shipping output=shipping | stats sum(shipping) as total_shipping",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_traffic_with_outages": {
			"name": "Traffic with Outages",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:access_combined\" | timechart span=15m count as Traffic \n| eval Outage=if(Traffic<20 AND strftime(_time,\"%H\")>=\"08\" AND strftime(_time,\"%H\")<=\"20\", 400, null())",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_unique_customers": {
			"name": "Unique Customers",
			"options": {
				"query": "index=fake_tshrt sourcetype=\"FAKE:online:order\" | spath path=customer.customerId output=cid | stats dc(cid) as unique_customers",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_v6bfOS5r": {
			"name": "Source",
			"options": {
				"query": "| tstats dc(source) where index=fake_tshrt",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_vGkkFAWv": {
			"name": "Teardown over time",
			"options": {
				"extend": "ds_0sYasD3M",
				"query": "| table _time teardown"
			},
			"type": "ds.chain"
		},
		"ds_x216uVgk": {
			"name": "Total Events",
			"options": {
				"query": "| tstats c where index=fake_tshrt ",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		}
	},
